import itertools
import json

def solve():
    # Input variables
    houses = [1, 2]  # House numbers from left (1) to right (2)
    Names = ["Eric", "Arnold"]
    HouseStyle = ["victorian", "colonial"]
    Smoothie = ["cherry", "desert"]
    Pet = ["dog", "cat"]

    solutions = []

    # Iterate over all permutations for each category
    for names_by_house in itertools.permutations(Names):
        for housestyle_by_house in itertools.permutations(HouseStyle):
            # Early check for constraint 3 (victorian is left of Eric)
            try:
                if housestyle_by_house.index("victorian") >= names_by_house.index("Eric"):
                    continue
            except ValueError:
                continue

            for smoothie_by_house in itertools.permutations(Smoothie):
                for pet_by_house in itertools.permutations(Pet):
                    # Apply constraints:

                    # 1. Cherry smoothie person == dog owner
                    if smoothie_by_house.index("cherry") != pet_by_house.index("dog"):
                        continue

                    # 2. Victorian house person == dog owner
                    if housestyle_by_house.index("victorian") != pet_by_house.index("dog"):
                        continue

                    # 3. Victorian house is somewhere to the left of Eric (already partially checked)
                    if housestyle_by_house.index("victorian") >= names_by_house.index("Eric"):
                        continue

                    # If all constraints satisfied, store the solution
                    solution = {
                        "solution": {
                            "header": ["House", "Name", "HouseStyle", "Smoothie", "Pet"],
                            "rows": []
                        }
                    }
                    for i, house in enumerate(houses):
                        row = [
                            str(house),
                            names_by_house[i],
                            housestyle_by_house[i],
                            smoothie_by_house[i],
                            pet_by_house[i]
                        ]
                        solution["solution"]["rows"].append(row)
                    solutions.append(solution)

    # Assuming a unique solution; if multiple, take the first
    if solutions:
        return solutions[0]
    else:
        # In case no solution found (should not happen with given constraints)
        return {
            "solution": {
                "header": ["House", "Name", "HouseStyle", "Smoothie", "Pet"],
                "rows": []
            }
        }

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
